import '@/styles/forms.css'
import { Controller, DefaultValues, SubmitHandler, useForm } from "react-hook-form";
import ReactDatePicker from "react-datepicker";

enum GenderEnum {
    female = "female",
    male = "male",
    other = "other",
}
interface IFormInput {
    firstName: String;
    lastName: String;
    nickName: String;
    email: String;
    password: String;
    dateOfBirth: Date;
    gender: GenderEnum;
    mobile: String;
    address: String;
    ReactDatepicker: Date;
}


const Register = () => {
    const { register, handleSubmit, control } = useForm<IFormInput>();

    const onSubmit: SubmitHandler<IFormInput> = (data) => alert(JSON.stringify(data));
    return (
        <form onSubmit={handleSubmit(onSubmit)}>
            <div>
                <label>First Name: </label>
                <input {...register("firstName")} />
            </div>
            <div>
                <label>Last Name: </label>
                <input {...register("lastName")} />
            </div>
            <div>
                <label>Nick Name: </label>
                <input {...register("nickName")} />
            </div>
            <div>
                <label>e-mail: </label>
                <input {...register("email")} />
            </div>


            <div>
                <label>Password: </label>
                <input {...register("password")} />
            </div>
            <div>
                <label>Date of Birth: </label>
                <Controller<IFormInput>
                    control={control}
                    name="ReactDatepicker"
                    render={({ field: { value, ...fieldProps } }) => {
                        return (
                            <ReactDatePicker
                                {...fieldProps}
                                className="input"
                                placeholderText="Select date"
                                selected={value instanceof Date ? value : null}
                            />
                        );
                    }}
                />
            </div>
            <div>
                <label>Gender: </label>
                <select {...register("gender")}>
                    <option value="female">female</option>
                    <option value="male">male</option>
                    <option value="other">other</option>
                </select>
            </div>
            <div>
                <label>Mobile: </label>
                <input {...register("mobile")} />
            </div>


            <div>
                <label>Address: </label>
                <input {...register("address")} />
            </div>
            <input type="submit" />
        </form>
    );
};


export default Register;